// LangGraph Swarm with Initial Greeting Support
// Combines swarm pattern with greeting functionality

const { ChatOpenAI } = require('@langchain/openai');
const { HumanMessage, AIMessage, SystemMessage } = require('@langchain/core/messages');

// Get input data
const inputData = $input.first().json.body;
const { expedition, chatHistory, message } = inputData;
const agents = expedition.agents || [];

// Validate API key
const OPENAI_API_KEY = $env.OPENAI_API_KEY || 'sk-YOUR-API-KEY';
if (!OPENAI_API_KEY || OPENAI_API_KEY === 'sk-YOUR-API-KEY') {
  return [{
    json: {
      message: "Please configure your OpenAI API key in the workflow.",
      agentReady: false,
      missionStatus: 'error',
      workflowId: $workflow.id
    }
  }];
}

if (agents.length === 0) {
  return [{
    json: {
      message: "⚠️ No agents assigned to this expedition.",
      agentReady: false,
      missionStatus: 'no_agents',
      shouldTerminateChat: true,
      workflowId: $workflow.id
    }
  }];
}

// Check if this is an initial greeting request
const isInitialGreeting = message === "[SYSTEM_INITIAL_GREETING]";

// Check conversation state
let isAgentReady = chatHistory?.some(msg => 
  msg.role === 'assistant' && 
  msg.content.toLowerCase().includes('i am ready to execute the mission')
) || false;

const userWantsToExecute = !isInitialGreeting && message.toLowerCase().match(/\b(execute|start|begin|launch|go)\b/);

if (isAgentReady && userWantsToExecute) {
  return [{
    json: {
      message: "🚀 MISSION EXECUTION INITIATED!\n\nAll systems are go! The expedition is now underway.",
      agentReady: true,
      missionStatus: 'executing',
      isExecuting: true,
      shouldTerminateChat: true,
      workflowId: $workflow.id
    }
  }];
}

// Initialize LLM
const llm = new ChatOpenAI({
  apiKey: OPENAI_API_KEY,
  model: 'gpt-4-turbo-preview',
  temperature: 0.7
});

// Implement Swarm Pattern with Greeting Support
// Step 1: Create agent definitions following swarm pattern
const agentDefinitions = agents.map(agent => ({
  name: agent.name,
  description: agent.description,
  instructions: `You are ${agent.name}, specializing in ${agent.description}.

Expedition: ${expedition.name} - ${expedition.description}

Your team:
${agents.map(a => `- ${a.name}: ${a.description}`).join('\n')}

Instructions:
1. Focus ONLY on your area of expertise (${agent.description})
2. Ask 2-3 specific questions related to your specialty
3. If a topic is outside your expertise, say: "Let me transfer you to [agent name] who specializes in [topic]."
4. Be concise and professional
5. When the team has gathered all necessary information, say: "I am ready to execute the mission."

Available transfers:
${agents.filter(a => a.id !== agent.id).map(a => `- transfer_to_${a.name.toLowerCase().replace(/\s+/g, '_')}: Transfer to ${a.name} for ${a.description}`).join('\n')}`,
  greetingInstructions: `You are ${agent.name}, specializing in ${agent.description}.

You're part of an expedition: ${expedition.name} - ${expedition.description}.

Your team includes:
${agents.map(a => `- ${a.name}: ${a.description}`).join('\n')}

This is the start of a new expedition conversation. Generate a SHORT, warm greeting that:
1. Briefly introduce yourself (one sentence)
2. Ask ONE specific, focused question related to your expertise to get started

Keep it simple, conversational, and under 3 sentences total. Don't overwhelm with information.

IMPORTANT: Do NOT add any signature or name at the end of your message. Your name is already shown in the chat interface.`,
  transferFunctions: agents.filter(a => a.id !== agent.id).map(targetAgent => ({
    name: `transfer_to_${targetAgent.name.toLowerCase().replace(/\s+/g, '_')}`,
    targetAgent: targetAgent.name
  }))
}));

// Step 2: Determine which agent should handle the message
let currentAgent = agentDefinitions[0];

if (!isInitialGreeting) {
  // Normal message - route based on content using swarm logic
  const messageLC = message.toLowerCase();
  for (const agentDef of agentDefinitions) {
    const keywords = agentDef.description.toLowerCase().split(' ');
    if (keywords.some(keyword => messageLC.includes(keyword))) {
      currentAgent = agentDef;
      break;
    }
  }
} else {
  // For initial greeting, select the agent most relevant to the expedition
  const expeditionKeywords = expedition.description.toLowerCase().split(' ');
  for (const agentDef of agentDefinitions) {
    const agentKeywords = agentDef.description.toLowerCase().split(' ');
    if (agentKeywords.some(keyword => expeditionKeywords.includes(keyword))) {
      currentAgent = agentDef;
      break;
    }
  }
}

// Step 3: Build conversation context
const messages = [];

// Add appropriate instructions based on greeting vs normal conversation
if (isInitialGreeting) {
  messages.push(new SystemMessage(currentAgent.greetingInstructions));
  messages.push(new HumanMessage("Please provide your initial greeting and questions."));
} else {
  messages.push(new SystemMessage(currentAgent.instructions));

  // Add chat history
  if (chatHistory && chatHistory.length > 0) {
    chatHistory.forEach(msg => {
      messages.push(msg.role === 'user' ? new HumanMessage(msg.content) : new AIMessage(msg.content));
    });
  }

  // Add current message
  messages.push(new HumanMessage(message));
}

// Step 4: Get agent response
try {
  const response = await llm.invoke(messages);
  const responseContent = response.content;

  // Step 5: Check for transfer requests (not applicable for initial greeting)
  let transferTo = null;
  if (!isInitialGreeting) {
    const transferMatch = responseContent.match(/transfer you to ([^\s]+)/i);
    if (transferMatch) {
      const requestedAgent = transferMatch[1].toLowerCase();
      const targetAgentDef = agentDefinitions.find(a => 
        a.name.toLowerCase() === requestedAgent ||
        a.name.toLowerCase().includes(requestedAgent)
      );
      if (targetAgentDef) {
        transferTo = targetAgentDef.name;
      }
    }
  }

  // Step 6: Check if ready to execute (not for initial greeting)
  const declaringReady = !isInitialGreeting && responseContent.toLowerCase().includes('i am ready to execute the mission');

  // Step 7: Format response with agent name
  let finalMessage = responseContent;
  if (transferTo) {
    finalMessage = `[Transferring from ${currentAgent.name} to ${transferTo}]\n\n${responseContent}`;
  }

  return [{
    json: {
      message: `[${currentAgent.name}]: ${finalMessage}`,
      agentReady: declaringReady || isAgentReady,
      missionStatus: declaringReady || isAgentReady ? 'ready_to_execute' : 'gathering_requirements',
      isExecuting: false,
      shouldTerminateChat: false,
      workflowId: $workflow.id,
      timestamp: new Date().toISOString(),
      metadata: {
        respondingAgent: currentAgent.name,
        transferTo: transferTo,
        availableAgents: agents.map(a => a.name),
        swarmPattern: true,
        isInitialGreeting: isInitialGreeting
      }
    }
  }];
} catch (error) {
  return [{
    json: {
      message: `[${currentAgent.name}]: I apologize, but I encountered an error. Please try again.`,
      agentReady: false,
      missionStatus: 'error',
      workflowId: $workflow.id,
      error: error.message
    }
  }];
}
